              setIsAnalyzing={setIsAnalyzing}
              searchError={searchError}
              setSearchError={setSearchError}
              allLocal={allLocal}
              activeDiet={activeDiet}
            />
\`;
mealPlate = mealPlate.replace(ui, replacementProps);

